class Envelope(val body: Message, val slip: List<String>, var cursor: Int = 0)
val registry: Map<String, suspend (Message) -> Message> = mapOf(
    "validate" to ::validate, "reserve" to ::reserve, "charge" to ::charge)
suspend fun advance(e: Envelope): Message {
    while (e.cursor < e.slip.size) {
        val step = registry[e.slip[e.cursor]] ?: error("unknown step")
        e.body = step(e.body)
        e.cursor++
    }
    return e.body
}
